<?php

namespace Malzariey\FilamentDaterangepickerFilter\Support;

/**
 * Reads month, weekday and meridiem names the way the browser wrote them.
 *
 * The picker formats its state with Day.js in the page locale, so with a
 * display format such as "F Y" an Arabic page writes "أكتوبر 2026".
 * Carbon::createFromFormat() only reads English names, and Carbon's own
 * translations are not Day.js's ("Okt" vs "Okt.", "אוק׳" vs "אוק",
 * "بعد از ظهر" vs "PM"), so this swaps each localized name for its English
 * equivalent using Day.js's own tables (resources/dayjs-locale-names.json,
 * generated by bin/build-locale-names.js), and the caller parses the result
 * as before.
 *
 * @internal Not part of the public API; it may change in any release.
 */
final class DayjsDateNames
{
    /** PHP format characters whose value is a name. */
    private const NAME_TOKENS = ['F', 'M', 'D', 'l', 'A', 'a'];

    /** PHP format characters that consume input (everything else is literal). */
    private const VALUE_TOKENS = 'dDjlNSwzWFmMntLoYyaABgGhHisuveIOPpTZcrU?*+#';

    private const ENGLISH_MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];

    private const ENGLISH_WEEKDAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];

    private static ?array $data = null;

    /**
     * The Day.js locale the picker's setLocale() ends up on for a PHP locale.
     *
     * Mirrors the JavaScript: its map first, then the lower-cased code with
     * the first "_" as "-", which Day.js shortens to the language ("ar_SA" →
     * "ar-sa" → "ar") and otherwise ignores, staying on "en".
     */
    public static function dayjsLocale(string $locale): string
    {
        $data = self::data();
        $candidate = strtolower($data['map'][$locale] ?? preg_replace('/_/', '-', strtolower($locale), 1));

        if (in_array($candidate, $data['available'], true)) {
            return $candidate;
        }

        $language = explode('-', $candidate)[0];

        if (str_contains($candidate, '-') && in_array($language, $data['available'], true)) {
            return $language;
        }

        return 'en';
    }

    /** Whether the format writes any name (month, weekday, AM/PM). */
    public static function formatHasNames(string $format): bool
    {
        foreach (self::tokenize($format) as [$type, $char]) {
            if ($type === 'name') {
                return true;
            }
        }

        return false;
    }

    /**
     * $value with each name Day.js wrote in $locale replaced by the English
     * one createFromFormat() reads, or null when it does not have that shape.
     */
    public static function toEnglish(string $value, string $format, string $locale): ?string
    {
        return self::readIn($value, $format, self::dayjsLocale($locale));
    }

    /**
     * Every English reading of $value: in $locale first, then in each other
     * locale the picker bundles.
     *
     * The page locale is not always the one the browser wrote in: Livewire
     * update requests skip non-persistent middleware, so a panel that sets
     * the locale there filters in "en", and a user may switch language with
     * a filter persisted in the session. No name in the bundled Day.js tables
     * means one date in one locale and another date in a different one
     * (tests/js/DateRangePickerLocaleNames.test.js keeps it that way), so a
     * reading in another locale is never a different date.
     *
     * @return list<string>
     */
    public static function englishReadings(string $value, string $format, string $locale): array
    {
        $preferred = self::dayjsLocale($locale);
        $locales = array_values(array_unique([$preferred, ...self::data()['available']]));
        $readings = [];

        foreach ($locales as $dayjsLocale) {
            $english = self::readIn($value, $format, $dayjsLocale);

            if ($english !== null && $english !== $value && ! in_array($english, $readings, true)) {
                $readings[] = $english;
            }
        }

        return $readings;
    }

    private static function readIn(string $value, string $format, string $dayjsLocale): ?string
    {
        $names = self::data()['names'][$dayjsLocale] ?? null;

        if ($names === null) {
            return null;
        }

        $segments = self::tokenize($format);
        $pattern = '';

        foreach ($segments as [$type, $char]) {
            $pattern .= match ($type) {
                'literal' => preg_quote($char, '/'),
                'value' => '(.*?)',
                'name' => '(' . self::alternation($names, $char) . ')',
                default => '',
            };
        }

        if (preg_match('/^' . $pattern . '$/iu', $value, $matches) !== 1) {
            return null;
        }

        // Pair every captured group with its token, in order.
        $captures = [];
        $group = 1;

        foreach ($segments as $index => [$type, $char]) {
            if ($type === 'value' || $type === 'name') {
                $captures[$index] = $matches[$group++] ?? '';
            }
        }

        $hour12 = null;

        foreach ($segments as $index => [$type, $char]) {
            if ($type === 'value' && ($char === 'g' || $char === 'h')) {
                $hour12 = (string) (int) $captures[$index];
            }
        }

        $english = '';

        foreach ($segments as $index => [$type, $char]) {
            if ($type === 'literal') {
                $english .= $char;

                continue;
            }

            if ($type === 'value') {
                $english .= $captures[$index];

                continue;
            }

            if ($type !== 'name') {
                continue;
            }

            $translated = self::englishName($names, $char, $captures[$index], $hour12);

            if ($translated === null) {
                return null;
            }

            $english .= $translated;
        }

        return $english;
    }

    /**
     * The format as [type, char] segments: "literal", "value" (a token whose
     * text is copied as-is), "name" (F M D l A a) or "modifier" (! |).
     *
     * @return list<array{0: string, 1: string}>
     */
    private static function tokenize(string $format): array
    {
        $segments = [];
        $chars = mb_str_split($format);
        $length = count($chars);

        for ($i = 0; $i < $length; $i++) {
            $char = $chars[$i];

            if ($char === '\\') {
                $i++;

                if ($i < $length) {
                    $segments[] = ['literal', $chars[$i]];
                }

                continue;
            }

            if ($char === '!' || $char === '|') {
                $segments[] = ['modifier', $char];
            } elseif (in_array($char, self::NAME_TOKENS, true)) {
                $segments[] = ['name', $char];
            } elseif (str_contains(self::VALUE_TOKENS, $char)) {
                $segments[] = ['value', $char];
            } else {
                $segments[] = ['literal', $char];
            }
        }

        return $segments;
    }

    private static function alternation(array $names, string $token): string
    {
        $candidates = match ($token) {
            'A', 'a' => array_keys($names['meridiem'][$token]),
            default => array_merge(...self::table($names, $token)),
        };

        // Longest first, so "تشرینی دووەم" is not read as a shorter prefix.
        $candidates = array_unique(array_map('strval', $candidates));
        usort($candidates, fn (string $a, string $b): int => mb_strlen($b) <=> mb_strlen($a));

        return implode('|', array_map(fn (string $name): string => preg_quote($name, '/'), $candidates));
    }

    /** @return list<list<string>> */
    private static function table(array $names, string $token): array
    {
        return match ($token) {
            'F' => $names['months'],
            'M' => $names['monthsShort'],
            'l' => $names['weekdays'],
            'D' => $names['weekdaysShort'],
        };
    }

    private static function englishName(array $names, string $token, string $text, ?string $hour12): ?string
    {
        if ($token === 'A' || $token === 'a') {
            $entry = null;

            foreach ($names['meridiem'][$token] as $name => $meridiem) {
                if (mb_strtolower((string) $name) === mb_strtolower($text)) {
                    $entry = $meridiem;

                    break;
                }
            }

            // Text shared by AM and PM hours (zh-cn "中午"): the hour decides.
            if (is_array($entry)) {
                $entry = $hour12 === null ? null : ($entry[$hour12] ?? null);
            }

            if ($entry === null) {
                return null;
            }

            return $token === 'a' ? strtolower($entry) : $entry;
        }

        foreach (self::table($names, $token) as $index => $variants) {
            foreach ($variants as $variant) {
                if (mb_strtolower($variant) === mb_strtolower($text)) {
                    return match ($token) {
                        'F' => self::ENGLISH_MONTHS[$index],
                        'M' => substr(self::ENGLISH_MONTHS[$index], 0, 3),
                        'l' => self::ENGLISH_WEEKDAYS[$index],
                        'D' => substr(self::ENGLISH_WEEKDAYS[$index], 0, 3),
                    };
                }
            }
        }

        return null;
    }

    private static function data(): array
    {
        return self::$data ??= json_decode(
            file_get_contents(__DIR__ . '/../../resources/dayjs-locale-names.json'),
            true,
            flags: JSON_THROW_ON_ERROR,
        );
    }
}
